import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  sessions: defineTable({
    sessionId: v.string(),
    expiresAt: v.number(),
  }),
});

import { mutation, query } from "./_generated/server";
import { v } from "convex/values";

export const insertSession = mutation({
  args: { sessionId: v.string(), expiresAt: v.number() },
  handler: async (ctx, args) => {
    await ctx.db.insert("sessions", {
      sessionId: args.sessionId,
      expiresAt: args.expiresAt,
    });
  },
});

export const getSessions = query({
  args: {},
  handler: async (ctx) => {
    return await ctx.db.query("sessions").collect();
  },
});

export const clearExpired = mutation({
  args: {},
  handler: async (ctx) => {
    const now = Date.now();
    const expiredSessions = await ctx.db
      .query("sessions")
      .filter((q) => q.lt(q.field("expiresAt"), now))
      .collect();

    for (const session of expiredSessions) {
      await ctx.db.delete(session._id);
    }
  },
});

import { cronJobs } from "convex/server";
import { api } from "./_generated/api";

const crons = cronJobs();

crons.hourly(
  "clear expired sessions",
  { hourBasic: 0 }, // This is ignored by hourly but required by some older versions of the API or just good practice to be aware of. Actually crons.hourly doesn't take this in modern Convex.
  api.sessions.clearExpired,
);

export default crons;

